"""Disk side of attachments: where files live and how they are removed."""
import os
from typing import Iterable

from app.config import settings


def file_path(stored_name: str) -> str:
    # stored_name is generated by us (uuid + extension), never taken from the user.
    return os.path.join(settings.upload_dir, stored_name)


def remove_files(stored_names: Iterable[str]) -> None:
    for name in stored_names:
        try:
            os.remove(file_path(name))
        except FileNotFoundError:
            pass
        except OSError:
            # A leftover file is harmless compared to failing a request that already succeeded.
            pass
